<?php use App\Core\Csrf; $title = 'Exam | LearnSpace'; require __DIR__ . '/_header.php'; ?>
<a href="/student/course?id=<?= $exam['course_id'] ?>" class="back-link">← Return to course</a><h1 data-no-translate><?= h($exam['title']) ?></h1><p class="muted">Attempt <?= h($attempt) ?> of <?= h($exam['max_attempts']) ?> · <?= h($exam['duration_minutes']) ?> minutes · Pass from <?= h($exam['passing_score']) ?> / <?= h($exam['total_points']) ?> points</p>
<section class="card"><form method="post" action="/student/exam"><?= Csrf::field() ?><input type="hidden" name="exam_id" value="<?= $exam['id'] ?>"><?php $currentQuestion = null; foreach ($questions as $row): ?><?php if ($currentQuestion !== $row['id']): if ($currentQuestion !== null) echo '</div>'; $currentQuestion = $row['id']; ?><div class="item"><h3 data-no-translate><?= h($row['question']) ?> <span class="muted">(<?= h($row['points']) ?> pts)</span></h3><?php if ($row['type'] === 'TEXT'): ?><textarea name="answer_text[<?= $row['id'] ?>]" required placeholder="Write your answer. Your professor will mark it manually."></textarea><?php endif; ?><?php endif; ?><?php if ($row['option_id']): ?><label class="row" data-no-translate><input type="<?= $row['allow_multiple'] ? 'checkbox' : 'radio' ?>" name="answer[<?= $row['id'] ?>][]" value="<?= $row['option_id'] ?>" <?= $row['allow_multiple'] ? '' : 'required' ?>> <?= h($row['option_text']) ?></label><?php endif; ?><?php endforeach; ?><?php if ($currentQuestion !== null) echo '</div>'; ?><button>Submit exam</button></form></section>
